SELECT 

FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_no LIKE CONCAT('%', #{param.budgetNo}, '%')


    AND budget_name LIKE CONCAT('%', #{param.budgetName}, '%')


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND budgeter_id = #{param.budgeterId}


    AND reviewer_id = #{param.reviewerId}


    AND approver_id = #{param.approverId}


    AND total_budget >= #{param.minTotalBudget}


    AND total_budget <= #{param.maxTotalBudget}


    AND budget_period_start >= #{param.budgetPeriodStart}


    AND budget_period_end <= #{param.budgetPeriodEnd}


    AND approval_date >= #{param.approvalStartDate}


    AND approval_date <= #{param.approvalEndDate}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}


    AND create_by = #{param.createBy}


    AND (budget_no LIKE CONCAT('%', #{param.keyword}, '%')
         OR budget_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR budget_description LIKE CONCAT('%', #{param.keyword}, '%')
         OR department_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR budget_manager_name LIKE CONCAT('%', #{param.keyword}, '%')
         OR remarks LIKE CONCAT('%', #{param.keyword}, '%'))

ORDER BY create_time DESC, id DESC

SELECT COUNT(1) > 0
FROM project_budget
WHERE budget_no = #{budgetNo}

    AND id != #{excludeId}

SELECT 

FROM project_budget
WHERE create_by = #{userId}
OR budget_manager_id = #{userId}
OR approver_id = #{userId}
ORDER BY create_time DESC

SELECT
    COUNT(*) as totalCount,
    COUNT(CASE WHEN budget_status = 1 THEN 1 END) as draftCount,
    COUNT(CASE WHEN budget_status = 2 THEN 1 END) as inProgressCount,
    COUNT(CASE WHEN budget_status = 3 THEN 1 END) as completedCount,
    COUNT(CASE WHEN approval_status = 1 THEN 1 END) as pendingApprovalCount,
    COUNT(CASE WHEN approval_status = 2 THEN 1 END) as approvedCount,
    COUNT(CASE WHEN approval_status = 3 THEN 1 END) as rejectedCount,
    COALESCE(SUM(total_budget), 0) as totalBudgetSum,
    COALESCE(SUM(used_budget), 0) as totalUsedBudget,
    COALESCE(SUM(remaining_budget), 0) as totalRemainingBudget,
    COALESCE(AVG(total_budget), 0) as avgTotalBudget,
    COUNT(CASE WHEN used_budget > total_budget THEN 1 END) as overBudgetCount,
    COUNT(CASE WHEN used_budget / total_budget >= 0.8 AND used_budget <= total_budget THEN 1 END) as tightBudgetCount
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND department_id = #{param.departmentId}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT
    budget_type as budgetType,
    COUNT(*) as count,
    COALESCE(SUM(total_budget), 0) as totalBudgetSum,
    COALESCE(SUM(used_budget), 0) as totalUsedBudget,
    COALESCE(AVG(total_budget), 0) as avgTotalBudget
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_status = #{param.budgetStatus}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY budget_type
ORDER BY totalBudgetSum DESC

SELECT
    budget_status as budgetStatus,
    COUNT(*) as count,
    COALESCE(SUM(total_budget), 0) as totalBudgetSum,
    COALESCE(SUM(used_budget), 0) as totalUsedBudget,
    COALESCE(AVG(total_budget), 0) as avgTotalBudget
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY budget_status
ORDER BY budget_status

SELECT
    department_id as departmentId,
    department_name as departmentName,
    COUNT(*) as count,
    COALESCE(SUM(total_budget), 0) as totalBudgetSum,
    COALESCE(SUM(used_budget), 0) as totalUsedBudget,
    COALESCE(AVG(total_budget), 0) as avgTotalBudget
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

GROUP BY department_id, department_name
ORDER BY totalBudgetSum DESC

SELECT DATE_FORMAT(budget_start_date, '%Y-%m') as month, COUNT(*) as count, COALESCE(SUM(total_budget), 0) as totalBudgetSum, COALESCE(SUM(used_budget), 0) as totalUsedBudget, COALESCE(AVG(total_budget), 0) as avgTotalBudget FROM project_budget WHERE budget_start_date >= DATE_SUB(SYSDATE, INTERVAL 12 MONTH)
AND project_id = #{param.projectId}
AND budget_type = #{param.budgetType}
AND budget_status = #{param.budgetStatus}
GROUP BY DATE_FORMAT(budget_start_date, '%Y-%m') ORDER BY month

SELECT COALESCE(SUM(total_budget), 0)
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT COALESCE(SUM(used_budget), 0)
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT
    CASE
        WHEN SUM(total_budget) = 0 THEN 0
        ELSE ROUND(SUM(used_budget) * 100.0 / SUM(total_budget), 2)
    END
FROM project_budget
WHERE 1=1

    AND project_id = #{param.projectId}


    AND budget_type = #{param.budgetType}


    AND budget_status = #{param.budgetStatus}


    AND budget_year = #{param.budgetYear}


    AND create_time >= #{param.createStartTime}


    AND create_time <= #{param.createEndTime}

SELECT
FROM project_budget WHERE budget_no LIKE CONCAT('%', #{keyword}, '%') OR budget_name LIKE CONCAT('%', #{keyword}, '%') OR budget_description LIKE CONCAT('%', #{keyword}, '%') OR department_name LIKE CONCAT('%', #{keyword}, '%') OR budget_manager_name LIKE CONCAT('%', #{keyword}, '%') ORDER BY create_time DESC
LIMIT #{limit}

SELECT budget_quarter as budgetQuarter, COUNT(*) as count, COALESCE(SUM(total_budget), 0) as totalBudgetSum, COALESCE(SUM(used_budget), 0) as totalUsedBudget, COALESCE(SUM(remaining_budget), 0) as totalRemainingBudget, COALESCE(AVG(total_budget), 0) as avgTotalBudget FROM project_budget WHERE budget_year = #{year}
AND budget_quarter = #{quarter}
GROUP BY budget_quarter ORDER BY budget_quarter

SELECT budget_month as budgetMonth, COUNT(*) as count, COALESCE(SUM(total_budget), 0) as totalBudgetSum, COALESCE(SUM(used_budget), 0) as totalUsedBudget, COALESCE(SUM(remaining_budget), 0) as totalRemainingBudget, COALESCE(AVG(total_budget), 0) as avgTotalBudget FROM project_budget WHERE budget_year = #{year}
AND budget_month = #{month}
GROUP BY budget_month ORDER BY budget_month

